SELECT
p.*,
pd.product_code,
pd.product_name
FROM mes_quality_plan p
LEFT JOIN mes_product_definition pd ON p.product_id = pd.id

    p.status != 'DELETED'

        AND p.plan_no LIKE CONCAT('%', #{query.planNo}, '%')


        AND p.plan_name LIKE CONCAT('%', #{query.planName}, '%')


        AND pd.product_code = #{query.productCode}


        AND p.batch_no = #{query.batchNo}


        AND p.plan_type = #{query.planType}


        AND p.status = #{query.status}


        AND p.inspector = #{query.inspector}


        AND p.plan_date >= #{query.planDateStart}


        AND p.plan_date <= #{query.planDateEnd}


        AND p.create_time >= #{query.createTimeStart}


        AND p.create_time <= #{query.createTimeEnd}


ORDER BY p.create_time DESC

SELECT

FROM mes_quality_plan
WHERE product_id = #{productId}

    AND status = #{status}

AND status != 'DELETED'
ORDER BY create_time DESC

SELECT status, COUNT(1) AS count FROM mes_quality_plan
status != 'DELETED'
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY status

SELECT DATE_FORMAT(create_time, '%Y-%m') AS month, COUNT(1) AS plan_count, SUM(CASE WHEN status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_count FROM mes_quality_plan
status != 'DELETED'
AND DATE(create_time) >= #{startDate}
AND DATE(create_time) <= #{endDate}
GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month ASC

SELECT pd.product_code, pd.product_name, COUNT(p.id) AS plan_count, SUM(CASE WHEN p.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_count FROM mes_quality_plan p LEFT JOIN mes_product_definition pd ON p.product_id = pd.id
p.status != 'DELETED'
AND DATE(p.create_time) >= #{startDate}
AND DATE(p.create_time) <= #{endDate}
GROUP BY pd.product_code, pd.product_name ORDER BY plan_count DESC
